// This module is configured as a serverExternalPackage so it is NOT processed
// by the bundler. It reads __NEXT_INVARIANTS__ from the runtime global on
// globalThis, not via defineEnv static replacement.
//
// Destructuring proves this is reading from the runtime global object — defineEnv
// only replaces full member expressions like __NEXT_INVARIANTS__.trailingSlash,
// not the bare __NEXT_INVARIANTS__ identifier used in destructuring.
module.exports.getInvariants = function getInvariants() {
  const { isDevServer, trailingSlash, experimentalOptimisticRouting } =
    __NEXT_INVARIANTS__
  return { isDevServer, trailingSlash, experimentalOptimisticRouting }
}
